-function applyFieldStyle(
+function shrinkToFit(
+	text: string,
+	font: PDFFont,
+	maxSize: number,
+	fieldWidth: number,
+	minSize = 6,
+	step = 0.5,
+): number {
+	if (!text) return maxSize;
+	for (let size = maxSize; size >= minSize; size -= step) {
+		if (font.widthOfTextAtSize(text, size) <= fieldWidth) {
+			return size;
+		}
+	}
+	return minSize;
+}
